insert into public.lessons (id, group_id, title, position, goal, content, example_prompt, task, youtube_url, published) values
  ('claude-1', 'claude', 'Знакомство с Claude: возможности и ограничения', 1,
   'Понять, с какими задачами Claude помогает хорошо, а где нужны осторожность и проверка.',
   'Claude — ИИ-ассистент, с которым общаются обычным языком в формате диалога. Он помогает писать и редактировать тексты, разбирать документы, объяснять сложные темы, придумывать идеи и раскладывать задачи на шаги. Программировать для этого не нужно: достаточно ясно описать, что вам требуется.

Ассистент составляет ответ на основе закономерностей, усвоенных при обучении, и того, что вы написали в диалоге. Поэтому он может звучать уверенно и при этом ошибаться: перепутать даты, цифры, названия или «додумать» несуществующий факт. Доступные возможности — например, поиск в интернете или работа с файлами — зависят от того, где и как вы им пользуетесь.

Отсюда главное правило курса: важные ответы проверяйте. Если речь о здоровье, деньгах, праве, учёбе с оценкой или рабочих решениях, сверяйтесь с первоисточниками и специалистами. ИИ ускоряет работу, но ответственность за итоговое решение остаётся за вами.

И о безопасности: не отправляйте в чат пароли, номера карт и чужие персональные данные. Для практики в курсе используйте вымышленные примеры.',
   'Я впервые пользуюсь ИИ-ассистентом. Расскажи простыми словами, с какими задачами ты можешь помочь студенту и офисному сотруднику, а в каких случаях твои ответы обязательно нужно перепроверять. Ответь двумя списками по 5 пунктов.',
   'Задайте Claude вопрос из своей повседневной жизни, например как распределить дела на неделю. Отметьте в ответе одно утверждение, которое стоило бы проверить, и запишите, где бы вы это сделали.',
   null, true),
  ('claude-2', 'claude', 'Как составить понятный запрос', 2,
   'Научиться формулировать запрос так, чтобы с первого раза получать полезный ответ.',
   'Качество ответа сильно зависит от запроса. Короткое «напиши письмо» оставляет ассистенту слишком много догадок: кому письмо, зачем, в каком тоне, какой длины. Чем меньше догадок, тем точнее результат.

Удобная схема из четырёх частей: контекст (кто вы и в какой ситуации), задача (что именно сделать), ограничения (объём, тон, что обязательно учесть) и формат ответа (список, таблица, письмо, несколько вариантов на выбор).

Не обязательно уложить всё в одно сообщение. Если результат не подошёл, уточните: «сделай короче», «убери канцелярит», «добавь пример». Можно попросить Claude сначала задать вам вопросы, которых не хватает для хорошего ответа.',
   'Я администратор вымышленной кофейни «Зерно». Нужно объявление для сотрудников о новом графике смен с 1-го числа. Тон — дружелюбный, но чёткий. Объём — до 80 слов. В конце — просьба подтвердить, что прочитали. Если для хорошего текста не хватает данных, сначала задай мне вопросы.',
   'Возьмите короткий запрос «Помоги с презентацией» и перепишите его по схеме: контекст, задача, ограничения, формат. Отправьте обе версии и сравните ответы.',
   null, true),
  ('claude-3', 'claude', 'Создание и редактирование текстов', 3,
   'Использовать Claude для черновиков, правки и смены стиля текста, сохраняя собственный голос.',
   'Claude помогает на всех этапах работы с текстом: набросать черновик, сократить длинный абзац, сделать тон официальнее или теплее, найти повторы и ошибки, предложить варианты заголовков.

Лучший результат получается, когда вы даёте материал: свои тезисы, факты, черновик. Тогда ассистент работает с вашим содержанием, а не придумывает своё. Просите объяснять правки — так вы увидите, что изменилось, и со временем начнёте писать лучше сами.

Обязательно перечитывайте итог. ИИ может сгладить важную мысль, добавить общие фразы или неточный факт. Если текст выходит под вашим именем, проверьте каждое утверждение — особенно цифры, даты и обещания.',
   'Вот черновик письма клиенту вымышленной студии «Ладья»: [вставить текст]. Сократи его примерно на треть и сделай вежливее, все даты и суммы оставь без изменений. После текста перечисли, какие правки ты внёс и почему.',
   'Возьмите свой короткий текст — сообщение, пост или абзац отчёта — и попросите Claude подготовить две версии: официальную и дружескую. Выберите лучшую и вручную исправьте в ней хотя бы одну фразу.',
   null, true),
  ('claude-4', 'claude', 'Работа с предоставленными текстами и документами', 4,
   'Научиться просить Claude пересказать, сравнить и разобрать текст, который вы ему даёте.',
   'Текст можно вставить в сообщение или, если сервис это поддерживает, приложить файлом. Затем попросите кратко пересказать его, выделить главное, составить список задач по протоколу встречи, найти противоречия или сравнить две версии документа.

Просите опираться только на предоставленный текст и указывать, откуда взят каждый вывод, — цитатой или номером пункта. Так проще проверить ответ и заметить, если ассистент что-то добавил от себя.

Перед загрузкой подумайте о конфиденциальности: уберите персональные данные, коммерческие тайны и всё, что вам не разрешено передавать сторонним сервисам. Для важных документов — договоров, медицинских заключений — пересказ ИИ не заменяет чтения оригинала и консультации специалиста.',
   'Ниже протокол вымышленной встречи команды проекта «Маяк». Опираясь только на этот текст, составь таблицу: задача, ответственный, срок. Если срок или ответственный не указаны, напиши «не указано» — ничего не придумывай. [вставить текст протокола]',
   'Возьмите статью или инструкцию на 1–2 страницы без личных данных и попросите Claude выделить 5 главных мыслей с цитатами. Проверьте по оригиналу, что каждая цитата там действительно есть.',
   null, true),
  ('claude-5', 'claude', 'Планирование и решение рабочих задач', 5,
   'Использовать Claude, чтобы разбить задачу на шаги, взвесить варианты и подготовиться к работе.',
   'Когда задача большая и непонятно, с чего начать, попросите ассистента разбить её на этапы со сроками. Опишите исходные условия: дедлайн, ресурсы, что уже сделано и что мешает.

Claude полезен как собеседник для размышлений: он может перечислить плюсы и минусы вариантов, предложить вопросы для коллег, найти слабые места в плане, подготовить повестку встречи или чек-лист.

Решение остаётся за вами. План от ИИ — это черновик: сверяйте его с реальными сроками, правилами организации и мнением людей, которых он касается. Попросите ассистента перечислить допущения, на которых построен план, — их и нужно проверить в первую очередь.',
   'Я координатор вымышленного благотворительного забега «Северный ветер». До мероприятия 6 недель, в команде 3 волонтёра. Составь план по неделям: задачи, кто отвечает, что может пойти не так. В конце перечисли допущения, которые ты сделал.',
   'Выберите реальную задачу на ближайшие две недели. Попросите Claude разбить её на шаги и перечислить допущения. Отметьте неверные допущения и попросите скорректировать план.',
   null, true),
  ('claude-6', 'claude', 'Итоговая практика: решение собственной задачи', 6,
   'Применить приёмы курса к своей задаче — от первого запроса до проверенного результата.',
   'Выберите задачу, которая действительно нужна вам: письмо, план, разбор документа, подготовка к выступлению. Хорошая итоговая задача — небольшая, с понятным результатом и без чувствительных данных.

Пройдите весь цикл: сформулируйте запрос по схеме, получите первый ответ, уточните его минимум дважды и попросите ассистента самого найти слабые места в результате.

Завершите проверкой: сверьте факты и цифры, убедитесь, что итог соответствует цели, и доработайте текст своими словами. Запишите, какой запрос сработал лучше всего, — это ваш личный шаблон на будущее.',
   'Моя задача — подготовить 3-минутное выступление о результатах вымышленного проекта «Сад на крыше» для коллег. Факты: [перечислить]. Сначала задай мне до 5 уточняющих вопросов, затем предложи структуру, а после моего ответа — текст. В конце укажи, какие утверждения мне стоит проверить.',
   'Решите свою задачу с помощью Claude: начальный запрос, два уточнения, проверка результата. Сохраните финальный запрос как шаблон и в двух предложениях опишите, чем последний ответ отличается от первого.',
   null, true),
  ('chatgpt-1', 'chatgpt', 'Знакомство с ChatGPT: возможности и ограничения', 1,
   'Понять, чем ChatGPT полезен в повседневных задачах и почему его ответы нужно проверять.',
   'ChatGPT — ИИ-ассистент, с которым общаются в формате диалога. Он помогает писать тексты, придумывать идеи, объяснять темы, составлять планы и списки. Ассистент учитывает предыдущие сообщения в чате, поэтому разговор можно продолжать и уточнять ответ.

При этом ChatGPT не «знает» истину: он составляет наиболее вероятный ответ. Иногда это приводит к ошибкам — неверным фактам, несуществующим источникам, неточным расчётам. Доступные функции — поиск, работа с файлами, изображения — зависят от сервиса и режима, которым вы пользуетесь.

Поэтому важные ответы проверяйте по надёжным источникам, а вопросы здоровья, финансов и права обсуждайте со специалистами. Не передавайте в чат пароли, данные карт и личную информацию других людей.',
   'Объясни, как ты можешь помочь мне в учёбе и на работе. Приведи по 3 примера задач и для каждого напиши, что в твоём ответе мне нужно будет проверить самостоятельно.',
   'Попросите ChatGPT назвать три факта о любом городе и проверьте их по надёжному источнику. Запишите, все ли факты оказались точными.',
   null, true),
  ('chatgpt-2', 'chatgpt', 'Как составить запрос и уточнить ответ', 2,
   'Освоить структуру запроса и приём последовательных уточнений.',
   'Хороший запрос отвечает на вопросы: что нужно сделать, для кого и зачем, какие есть ограничения и в каком виде нужен результат. Полезно приложить пример того, что вам нравится, — ассистент подстроится под стиль.

Первый ответ — это черновик. Уточняйте его по одному параметру: «короче», «проще, для школьника», «оформи таблицей», «предложи ещё три варианта». Так легче понять, какое изменение дало эффект.

Если разговор ушёл не туда, проще начать новый чат с улучшенным запросом, чем долго исправлять старый. Удачные формулировки сохраняйте — со временем из них сложится собственная библиотека шаблонов.',
   'Нужно поздравление для коллеги Ольги (вымышленный пример) с 5-летием работы в компании. Тон — тёплый, без пафоса, 3–4 предложения. Пример стиля, который мне нравится: «Спасибо, что с тобой всё получается проще». Дай 3 варианта.',
   'Получите ответ на простой запрос, а затем уточните его три раза, каждый раз меняя один параметр: длину, тон, формат. Запишите, какое уточнение изменило ответ сильнее всего.',
   null, true),
  ('chatgpt-3', 'chatgpt', 'Тексты, идеи и создание контента', 3,
   'Использовать ChatGPT для мозгового штурма, черновиков и адаптации материалов под разные площадки.',
   'Для поиска идей просите количество и разнообразие: «20 вариантов названий в трёх разных стилях». Из большого списка легче выбрать и доработать лучшее, чем ждать одного идеального варианта.

Один материал можно адаптировать под разные форматы: пост для соцсети, короткое сообщение в рабочий чат, текст рассылки. Укажите аудиторию, площадку и желаемый объём.

Помните об ответственности: проверяйте факты в публикуемом тексте, не выдавайте чужие идеи за свои и соблюдайте правила своей площадки, учебного заведения или работодателя об использовании ИИ. Добавьте собственные примеры и опыт — так текст станет живым и узнаваемым.',
   'Я веду страницу вымышленной городской библиотеки «Книжный двор». Предложи 10 идей постов на месяц для взрослых читателей: тема, короткая подводка, формат (опрос, подборка, история). Избегай рекламных клише.',
   'Попросите ChatGPT предложить 15 идей для своего проекта, хобби или учебной работы. Выберите две лучшие и попросите развернуть каждую в короткий план.',
   null, true),
  ('chatgpt-4', 'chatgpt', 'Помощь в обучении и объяснение сложных тем', 4,
   'Научиться использовать ChatGPT как репетитора, который объясняет, а не делает работу за вас.',
   'Попросите объяснить тему на вашем уровне: «как для новичка», «на примере из повседневной жизни», «по шагам». Если что-то непонятно, задавайте уточняющие вопросы — это нормальная часть обучения.

Сильный приём — попросить ассистента проверить вас: задать вопросы по теме, дать задачу и разобрать вашу ошибку. Так знания закрепляются лучше, чем при чтении готового ответа.

Ассистент может ошибаться в формулах, датах и определениях, поэтому сверяйтесь с учебником или конспектом. Соблюдайте правила своего учебного заведения: использовать ИИ для понимания темы полезно, а сдавать сгенерированный текст как свой обычно запрещено.',
   'Я готовлюсь к зачёту по экономике. Объясни понятие «инфляция» простыми словами на бытовом примере, а затем задай мне 3 вопроса, чтобы проверить понимание. Не давай ответы сразу — дождись моих.',
   'Выберите тему, которая даётся вам трудно. Попросите объяснение на бытовом примере и 3 проверочных вопроса. Ответьте на них и попросите разобрать ваши ошибки.',
   null, true),
  ('chatgpt-5', 'chatgpt', 'Планирование и повседневные задачи', 5,
   'Применять ChatGPT для планирования времени, покупок, поездок и бытовых дел.',
   'ChatGPT помогает превратить хаотичный список дел в план: распределить задачи по дням, учесть приоритеты, оставить время на отдых. Чем точнее вы опишете ограничения — рабочие часы, бюджет, предпочтения, — тем полезнее результат.

Типичные задачи: меню на неделю со списком покупок, чек-лист сборов в поездку, план подготовки к переезду, распорядок дня перед экзаменом.

Проверяйте всё, что зависит от реального мира: часы работы, расписание транспорта, цены и правила могут оказаться устаревшими или неточными. Сверяйте их на официальных сайтах, прежде чем полагаться на план.',
   'Составь меню ужинов на 5 будних дней для семьи из трёх человек. Ограничения: готовка до 40 минут, без грибов. Добавь общий список покупок, сгруппированный по отделам магазина.',
   'Опишите свои дела на ближайшую неделю и ограничения по времени. Попросите ChatGPT составить расписание, а затем исправьте в нём то, что не соответствует реальности.',
   null, true),
  ('chatgpt-6', 'chatgpt', 'Итоговая практика: решение собственной задачи', 6,
   'Самостоятельно решить свою задачу с ChatGPT и оценить результат по заранее заданному критерию.',
   'Выберите задачу из своей жизни — учебную, рабочую или бытовую. Сформулируйте, какой результат будет считаться успешным: например, «готовый план на месяц» или «письмо, которое можно отправить».

Работайте итерациями: запрос по структуре, оценка ответа по вашему критерию, уточнения. Попросите ассистента критически оценить собственный результат и предложить улучшения.

Завершите проверкой фактов и личной доработкой. Подведите итог: сколько времени удалось сэкономить, что пришлось исправлять вручную и какие запросы вы будете использовать снова.',
   'Помоги составить план обучения. Моя цель — уверенно пользоваться ИИ на работе. Мой уровень — новичок. Время на практику — 30 минут в день. Сначала задай уточняющие вопросы, затем предложи план на 2 недели с конкретными упражнениями.',
   'Решите свою задачу с ChatGPT, сделав минимум два уточнения. Оцените результат по заранее заданному критерию и запишите три вывода: что сработало, что пришлось исправить и какой запрос вы сохраните.',
   null, true)
on conflict (id) do nothing;

